internal fun videoId()=UUID.randomUUID().toString()
internal fun videoTime(ms:Long):String{val t=ms.coerceAtLeast(0);return "%d:%02d.%01d".format(t/60000,t/1000%60,t/100%10)}
internal data class VideoTitle(val id:String=videoId(),val text:String="Your text",val start:Long=0,val end:Long=3000,val x:Float=0f,val y:Float=-.65f,val size:Float=1f,val color:Int=-1,val background:Boolean=true,val bold:Boolean=true,val caption:Boolean=false,val entrance:String="None",val exit:String="None",val animationOffset:Long=0,val animationDuration:Long=0){
    fun json()=JSONObject().put("id",id).put("text",text).put("start",start).put("end",end).put("x",x).put("y",y).put("size",size).put("color",color).put("background",background).put("bold",bold).put("caption",caption).put("entrance",entrance).put("exit",exit).put("animationOffset",animationOffset).put("animationDuration",animationDuration)
    companion object{fun parse(j:JSONObject)=VideoTitle(j.getString("id"),j.getString("text").also{require(it.length<=1000)},j.getLong("start"),j.getLong("end"),j.getDouble("x").toFloat(),j.getDouble("y").toFloat(),j.getDouble("size").toFloat(),j.getInt("color"),j.getBoolean("background"),j.getBoolean("bold"),j.optBoolean("caption"),j.optString("entrance","None"),j.optString("exit","None"),j.optLong("animationOffset"),j.optLong("animationDuration"))}
}
internal data class VideoClip(val id:String=videoId(),val file:String,val name:String,val sourceMs:Long,val image:Boolean=false,val hasAudio:Boolean=true,val start:Long=0,val end:Long=sourceMs,val speed:Float=1f,val volume:Float=1f,val rotate:Int=0,val flipX:Boolean=false,val flipY:Boolean=false,val zoom:Float=1f,val panX:Float=0f,val panY:Float=0f,val endZoom:Float=1f,val motion:Boolean=false,val brightness:Float=0f,val contrast:Float=0f,val saturation:Float=0f,val hue:Float=0f,val warmth:Float=0f,val fadeIn:Long=0,val fadeOut:Long=0,val titles:List<VideoTitle> = emptyList(),val keyframes:List<VideoKeyframe> = emptyList(),val rates:List<VideoRate> = emptyList(),val transition:String="None",val transitionMs:Long=500,val lut:String="",val lutName:String="",val lutAmount:Float=1f){
    val duration get()=videoOutputDuration(start,end,speed,rates)
    fun json()=JSONObject().put("id",id).put("file",file).put("name",name).put("sourceMs",sourceMs).put("image",image).put("hasAudio",hasAudio).put("start",start).put("end",end).put("speed",speed).put("volume",volume).put("rotate",rotate).put("flipX",flipX).put("flipY",flipY).put("zoom",zoom).put("panX",panX).put("panY",panY).put("endZoom",endZoom).put("motion",motion).put("brightness",brightness).put("contrast",contrast).put("saturation",saturation).put("hue",hue).put("warmth",warmth).put("fadeIn",fadeIn).put("fadeOut",fadeOut).put("titles",JSONArray(titles.map{it.json()})).put("keyframes",JSONArray(keyframes.map{it.json()})).put("rates",JSONArray(rates.map{it.json()})).put("transition",transition).put("transitionMs",transitionMs).put("lut",lut).put("lutName",lutName).put("lutAmount",lutAmount)
    fun checked():VideoClip{require(transition in videoTransitions&&transitionMs in 0..2000&&lutAmount.isFinite()&&lutAmount in 0f..1f&&lutName.length<=120&&(lut.isEmpty()||lut.matches(Regex("[a-f0-9-]+\\.media"))));require(file.matches(Regex("[a-f0-9-]+\\.media")));require(sourceMs in 100..43_200_000&&start>=0&&end<=sourceMs&&end-start>=100&&speed.isFinite()&&speed in .25f..4f);require(volume.isFinite()&&volume in 0f..2f&&rotate in listOf(0,90,180,270));require(listOf(zoom,endZoom).all{it.isFinite()&&it in .1f..4f}&&listOf(panX,panY).all{it.isFinite()&&it in -1f..1f});require(listOf(brightness,contrast,warmth).all{it.isFinite()&&it in -1f..1f}&&saturation in -100f..100f&&hue in -180f..180f);require(fadeIn in 0..duration&&fadeOut in 0..duration);require(keyframes.size<=100&&rates.size<=100);require(keyframes.zipWithNext().all{it.first.at<it.second.at});keyframes.forEach{it.checked(duration)};require(rates.zipWithNext().all{it.first.at<it.second.at});rates.forEach{require(it.at in 0..sourceMs&&it.factor.isFinite()&&it.factor in .0625f..16f)};require(titles.size<=200);titles.forEach{require(it.start>=0&&it.end>it.start&&it.end<=duration&&it.size in .3f..3f&&it.x in -1f..1f&&it.y in -1f..1f&&it.entrance in videoTitleAnimations&&it.exit in videoTitleAnimations&&it.animationOffset in 0..43_200_000&&it.animationDuration in 0..43_200_000)};return this}
    companion object{fun parse(j:JSONObject)=VideoClip(id=j.getString("id"),file=j.getString("file"),name=j.getString("name"),sourceMs=j.getLong("sourceMs"),image=j.getBoolean("image"),hasAudio=j.getBoolean("hasAudio"),start=j.getLong("start"),end=j.getLong("end"),speed=j.getDouble("speed").toFloat(),volume=j.getDouble("volume").toFloat(),rotate=j.getInt("rotate"),flipX=j.getBoolean("flipX"),flipY=j.getBoolean("flipY"),zoom=j.getDouble("zoom").toFloat(),panX=j.getDouble("panX").toFloat(),panY=j.getDouble("panY").toFloat(),endZoom=j.getDouble("endZoom").toFloat(),motion=j.getBoolean("motion"),brightness=j.getDouble("brightness").toFloat(),contrast=j.getDouble("contrast").toFloat(),saturation=j.getDouble("saturation").toFloat(),hue=j.getDouble("hue").toFloat(),warmth=j.getDouble("warmth").toFloat(),fadeIn=j.getLong("fadeIn"),fadeOut=j.getLong("fadeOut"),titles=j.getJSONArray("titles").let{a->List(a.length()){VideoTitle.parse(a.getJSONObject(it))}},keyframes=j.optJSONArray("keyframes")?.let{a->List(a.length()){VideoKeyframe.parse(a.getJSONObject(it))}}?:emptyList(),rates=j.optJSONArray("rates")?.let{a->List(a.length()){VideoRate.parse(a.getJSONObject(it))}}?:emptyList(),transition=j.optString("transition","None"),transitionMs=j.optLong("transitionMs",500),lut=j.optString("lut"),lutName=j.optString("lutName"),lutAmount=j.optDouble("lutAmount",1.0).toFloat()).checked()}
}
internal data class VideoMusic(val id:String=videoId(),val file:String,val name:String,val sourceMs:Long,val start:Long=0,val end:Long=sourceMs,val offset:Long=0,val volume:Float=.5f,val fadeIn:Long=0,val fadeOut:Long=0,val speed:Float=1f,val rates:List<VideoRate> = emptyList(),val narration:Boolean=false,val duck:Boolean=false,val pan:Float=0f,val tone:String="Original",val pitch:Float=0f,val noise:Float=0f,val rumble:Boolean=false){
    val duration get()=videoOutputDuration(start,end,speed,rates)
    fun json()=JSONObject().put("id",id).put("file",file).put("name",name).put("sourceMs",sourceMs).put("start",start).put("end",end).put("offset",offset).put("volume",volume).put("fadeIn",fadeIn).put("fadeOut",fadeOut).put("speed",speed).put("rates",JSONArray(rates.map{it.json()})).put("narration",narration).put("duck",duck).put("pan",pan).put("tone",tone).put("pitch",pitch).put("noise",noise).put("rumble",rumble)
    companion object{fun parse(j:JSONObject)=VideoMusic(j.getString("id"),j.getString("file"),j.getString("name"),j.getLong("sourceMs"),j.getLong("start"),j.getLong("end"),j.getLong("offset"),j.getDouble("volume").toFloat(),j.getLong("fadeIn"),j.getLong("fadeOut"),j.optDouble("speed",1.0).toFloat(),j.optJSONArray("rates")?.let{a->List(a.length()){VideoRate.parse(a.getJSONObject(it))}}?:emptyList(),j.optBoolean("narration"),j.optBoolean("duck"),j.optDouble("pan",0.0).toFloat(),j.optString("tone","Original"),j.optDouble("pitch",0.0).toFloat(),j.optDouble("noise",0.0).toFloat(),j.optBoolean("rumble")).also{require(it.pitch.isFinite()&&it.pitch in -12f..12f&&it.noise.isFinite()&&it.noise in 0f..1f);require(it.pan.isFinite()&&it.pan in -1f..1f&&it.tone in videoAudioTones);require(it.file.matches(Regex("[a-f0-9-]+\\.media"))&&it.sourceMs in 100..43_200_000&&it.start>=0&&it.end<=it.sourceMs&&it.end>it.start&&it.offset>=0&&it.volume in 0f..2f&&it.fadeIn>=0&&it.fadeOut>=0);require(it.speed.isFinite()&&it.speed in .25f..4f&&it.rates.size<=100&&it.rates.zipWithNext().all{p->p.first.at<p.second.at});it.rates.forEach{r->require(r.at in 0..it.sourceMs&&r.factor.isFinite()&&r.factor in .0625f..16f)}}}
}
internal data class VideoProject(val id:String=videoId(),val name:String="Untitled video",val clips:List<VideoClip> = emptyList(),val music:List<VideoMusic> = emptyList(),val ratio:String="16:9",val fill:Boolean=false,val height:Int=1080,val fps:Int=30,val layers:List<VideoLayer> = emptyList(),val bitrate:Int=0,val beats:List<Long> = emptyList(),val previewHeight:Int=720){
    val duration get()=clips.sumOf{it.duration}-clips.indices.sumOf{videoOverlap(clips,it)}
    fun clipStart(index:Int)=clips.take(index).sumOf{it.duration}-(1..index).sumOf{videoOverlap(clips,it)}
    fun json()=JSONObject().put("schema",1).put("id",id).put("name",name).put("clips",JSONArray(clips.map{it.json()})).put("music",JSONArray(music.map{it.json()})).put("ratio",ratio).put("fill",fill).put("height",height).put("fps",fps).put("layers",JSONArray(layers.map{it.json()})).put("bitrate",bitrate).put("beats",JSONArray(beats)).put("previewHeight",previewHeight)
    fun split(index:Int,at:Long):VideoProject{val c=clips[index];val cut=videoSourceAt(c,at);require(cut-c.start>=100&&c.end-cut>=100){"Move the playhead away from the clip edges"}
        val leftDuration=videoOutputDuration(c.start,cut,c.speed,c.rates);val rightDuration=videoOutputDuration(cut,c.end,c.speed,c.rates);require(leftDuration>=2*videoOverlap(clips,index)&&rightDuration>=2*videoOverlap(clips,index+1)){"Leave room for the transition on both sides of the split"};val t=leftDuration.toFloat()/c.duration;val midZoom=c.zoom+(c.endZoom-c.zoom)*(t*t*(3-2*t))
        val left=c.copy(end=cut,keyframes=videoSplitKeys(c,leftDuration,true),endZoom=if(c.motion)midZoom else c.endZoom,fadeOut=0,fadeIn=c.fadeIn.coerceAtMost(leftDuration),titles=c.titles.filter{it.start<leftDuration}.map{it.copy(end=it.end.coerceAtMost(leftDuration),animationDuration=if(it.animationDuration>0)it.animationDuration else it.end-it.start)})
        val right=c.copy(id=videoId(),start=cut,transition="None",keyframes=videoSplitKeys(c,leftDuration,false).map{it.copy(at=it.at.coerceAtMost(rightDuration))}.distinctBy{it.at},zoom=if(c.motion)midZoom else c.zoom,fadeIn=0,fadeOut=c.fadeOut.coerceAtMost(rightDuration),titles=c.titles.filter{it.end>leftDuration}.map{it.copy(id=videoId(),start=(it.start-leftDuration).coerceAtLeast(0),end=(it.end-leftDuration).coerceAtMost(rightDuration),animationOffset=it.animationOffset+(leftDuration-it.start).coerceAtLeast(0),animationDuration=if(it.animationDuration>0)it.animationDuration else it.end-it.start)}.filter{it.end>it.start})
        return copy(clips=clips.take(index)+left+right+clips.drop(index+1))}
    companion object{fun parse(j:JSONObject):VideoProject{require(j.getInt("schema")==1);return VideoProject(j.getString("id"),j.getString("name"),j.getJSONArray("clips").let{a->List(a.length()){VideoClip.parse(a.getJSONObject(it))}},j.getJSONArray("music").let{a->List(a.length()){VideoMusic.parse(a.getJSONObject(it))}},j.getString("ratio"),j.getBoolean("fill"),j.getInt("height"),j.getInt("fps"),j.optJSONArray("layers")?.let{a->List(a.length()){VideoLayer.parse(a.getJSONObject(it))}}?:emptyList(),j.optInt("bitrate"),j.optJSONArray("beats")?.let{a->List(a.length()){a.getLong(it)}}?:emptyList(),j.optInt("previewHeight",720)).also{require(it.previewHeight in listOf(360,540,720)&&it.beats.size<=5000&&it.beats.all{b->b in 0..it.duration}&&it.beats.zipWithNext().all{(a,b)->a<b});require(it.id.matches(Regex("[a-f0-9-]+"))&&it.name.length in 1..120&&it.clips.size<=100&&it.music.size<=4&&it.duration<=43_200_000&&it.ratio in ratios&&it.height in listOf(480,720,1080,2160)&&it.fps in listOf(24,25,30,50,60)&&it.layers.size<=4&&it.bitrate in listOf(0,4_000_000,8_000_000,16_000_000,32_000_000));it.layers.forEach{v->require(v.offset in 0 until it.duration&&v.clip.duration<=it.duration-v.offset)};require(it.clips.sumOf{c->c.titles.size}<=5000)}}
        val ratios=listOf("16:9","9:16","1:1","4:5","4:3")
    }
}
internal class VideoStore(context:Context){
    val root=File(context.filesDir,"video-editor").apply{mkdirs()}
    fun folder(id:String):File{require(id.matches(Regex("[a-f0-9-]+")));return File(root,id).apply{mkdirs()}}
    private fun write(file:File,text:String){val a=AtomicFile(file);val out=a.startWrite();try{out.write(text.toByteArray(Charsets.UTF_8));a.finishWrite(out)}catch(e:Exception){a.failWrite(out);throw e}}
    fun save(p:VideoProject){
        val text=p.json().toString();VideoProject.parse(JSONObject(text))
        val folder=folder(p.id);val file=File(folder,"project.json")
        // Retain the last parseable revision; never replace recovery with a corrupt document.
        runCatching{AtomicFile(file).openRead().use{it.bufferedReader().readText()}.also{old->require(VideoProject.parse(JSONObject(old)).id==p.id)}}.getOrNull()?.let{write(File(folder,"recovery.json"),it)}
        write(file,text)
        // Publish the current-project pointer only after the project itself is durable.
        val pointer=File(root,"current.txt")
        val current=runCatching{AtomicFile(pointer).openRead().use{it.bufferedReader().readText()}}.getOrNull()
        if(current!=p.id)write(pointer,p.id)
    }
    private fun readProject(id:String,name:String)=AtomicFile(File(folder(id),name)).openRead().use{VideoProject.parse(JSONObject(it.bufferedReader().readText()))}.also{require(it.id==id)}
    fun load(id:String):VideoProject=runCatching{readProject(id,"project.json")}.getOrElse{readProject(id,"recovery.json")}
    fun missing(p:VideoProject)=VideoProjectArchive.files(p).filter{!File(folder(p.id),it).isFile||File(folder(p.id),it).length()==0L}
    fun current():VideoProject?{val f=AtomicFile(File(root,"current.txt"));return if(f.baseFile.exists()||File(root,"current.txt.bak").exists())load(f.openRead().use{it.bufferedReader().readText()})else null}
    fun list():List<VideoProject> = root.listFiles().orEmpty().filter{it.isDirectory}.sortedByDescending{File(it,"project.json").lastModified()}.mapNotNull{runCatching{load(it.name)}.getOrNull()}
    fun delete(id:String){check(folder(id).deleteRecursively()){"Unable to delete project"};val f=File(root,"current.txt");if(f.exists()&&f.readText()==id){f.delete();File(root,"current.txt.bak").delete()}}
}
